const getBookProjects=()=>{try{return JSON.parse(localStorage.getItem('bookProjects')||'[]')}catch{return []}};const normalizeAudience=value=>String(value||'').trim().replace(/\s+/g,' ').toLowerCase();const sameProjectContext=(p,book,audience,platform)=>normalizeBookName(p.book)===normalizeBookName(book)&&normalizeAudience(p.audience)===normalizeAudience(audience)&&(p.platform||'小红书')===(platform||'小红书');const findCachedBook=(book,audience,platform)=>{if(!normalizeAudience(audience))return null;return getBookProjects().find(p=>sameProjectContext(p,book,audience,platform)&&Array.isArray(p.topics)&&p.topics.length)};const findAnyCachedBook=book=>getBookProjects().find(p=>normalizeBookName(p.book)===normalizeBookName(book)&&Array.isArray(p.topics)&&p.topics.length);function setPlatform(platform){const button=document.querySelector(`#platforms button[data-platform="${platform}"]`);if(!button)return;document.querySelectorAll('#platforms button').forEach(x=>x.classList.toggle('active',x===button));$('#platformNote').textContent=platformNotes[platform]||''}function restoreProject(project,scroll=true){if(!project?.topics?.length)return false;matchedHistoryProject=project;$('#book').value=project.book;$('#audience').value=project.audience||'';setPlatform(project.platform||'小红书');const a=project.audienceAnalysis||{},groups=[['最关注的问题',a.mainProblems||[]],['情绪需求',a.emotionalNeeds||[]],['生活场景',a.lifeScenarios||[]],['内容偏好',a.paymentMotivations||[]]];$('#analysisTitle').textContent=`${project.audience||'目标用户'}真正关心什么？`;$('#insights').innerHTML=groups.map(g=>`<article class="insight"><h3>${g[0]}</h3>${g[1].map(x=>`<span>${escapeHtml(x)}</span>`).join('')}</article>`).join('');current=project.topics.map((t,i)=>({...t,id:i}));draw(current);resetQuotes();$('#results').classList.remove('hidden');if(scroll)$('#results').scrollIntoView({behavior:'smooth'});showAIStatus(`已找到《${project.book}》针对“${project.audience}”的${project.platform||'小红书'}历史选题，已直接展示。`,'success');toast('已恢复匹配当前目标用户的历史选题');return true}function saveBookProject(project){const projects=getBookProjects().filter(p=>!sameProjectContext(p,project.book,project.audience,project.platform));localStorage.setItem('bookProjects',JSON.stringify([project,...projects].slice(0,50)));localStorage.setItem('lastProject',JSON.stringify(project))}
