$('#quotesBtn').onclick=async()=>{const book=$('#book').value.trim(),audience=$('#audience').value.trim();if(!book||!audience)return toast('请先填写书名和目标用户');if(!documentContext)return toast('原文摘录需要先上传当前书籍文档');const btn=$('#quotesBtn');btn.classList.add('loading');btn.disabled=true;btn.querySelector('span').textContent='正在从源文档筛选 5 句原文…';showAIStatus('提取5句原文：正在建立源文档候选句并按目标用户筛选…');try{const data=await extractBookQuotes(book,audience,documentContext,documentName);quoteSeeds=data.quotes||[];if(quoteSeeds.length!==5)throw new Error(`仅返回 ${quoteSeeds.length} 句`);$('#quotesNote').textContent=`从《${book}》上传文档中直接提取 · 按与${audience}的相关度筛选`;$('#quotesGrid').innerHTML=quoteSeeds.map((q,i)=>`<article class="quote-card"><b>${String(i+1).padStart(2,'0')}</b><span>${escapeHtml(q.text)}</span><small>原文位置：${escapeHtml(q.location)} · ${escapeHtml(q.relevance)}</small><button class="quote-share" data-quote-image="${i}">生成图片</button></article>`).join('');document.querySelectorAll('[data-quote-image]').forEach(b=>b.onclick=()=>generateQuoteImage(Number(b.dataset.quoteImage)));$('#quotes').classList.remove('hidden');$('#quotes').scrollIntoView({behavior:'smooth'});showAIStatus('提取5句原文成功：展示文字直接来自上传文件，AI仅负责选择编号。','success');toast('已从源文档提取 5 句原文')}catch(err){showAIStatus(`提取5句原文失败：${err.message||'服务暂不可用'}`,'error');toast('提取5句原文失败')}finally{btn.classList.remove('loading');btn.disabled=false;btn.querySelector('span').textContent='重新提取强相关的 5 句原文'}};
let currentShareIndex=0;function visualHash(value){let hash=2166136261;for(const char of String(value||'')){hash^=char.codePointAt(0);hash=Math.imul(hash,16777619)}return hash>>>0}
function audienceTheme(audience,quote='',book='',location=''){const female=/妈妈|女性|宝妈|女孩/.test(audience),professional=/职场|管理|创业|老板/.test(audience),young=/孩子|学生|青少年/.test(audience),seed=visualHash(`${book}|${quote}|${audience}|${location}`);let mood=/苦难|困境|韧性|命运|崩溃|失去|活着|坚持|勇气/.test(quote)?'resilience':/家人|家庭|关系|彼此|照顾|爱|陪伴|理解/.test(quote)?'connection':/工作|职场|行动|目标|成长|选择|改变|学习/.test(quote)?'growth':/自由|远方|世界|旅行|探索|可能/.test(quote)?'explore':'calm';const palettes={resilience:[female?['#33454b','#cf836d','#f5e8d8','#182b30']:['#293d42','#b87350','#eee0c8','#16272b'],['#3d4038','#c47b55','#f0e5cd','#202722'],['#273b47','#be8f5e','#ebe4d7','#172833']],connection:[['#744342','#d5a08b','#f7ede2','#4c2d2d'],['#465b4d','#d49a7b','#f4ead9','#26382e'],['#6a4c56','#c99078','#f5e9df','#402d35']],growth:[professional?['#213944','#c79a54','#edf0ec','#132731']:['#355348','#d2a55e','#f2ead7','#223b33'],['#344b3f','#b98d52','#f1ead9','#1f3028'],['#294653','#cc8b58','#e9eee8','#172d35']],explore:[['#31545b','#d6a55b','#f1ead6','#18343b'],['#4a5b3f','#bf7652','#f4e8d5','#293524'],['#3b4b68','#cc9b62','#eee7d8','#222d42']],calm:[young?['#48715b','#e7b65c','#f7f1d8','#2a4939']:['#435b51','#b96e52','#f1e7d7','#283d36'],['#536249','#c88b62','#f4ead8','#303b2b'],['#3f5c60','#c5a36b','#eee9dc','#243b3d']]};const names={resilience:'沉静力量风',connection:'温暖关系风',growth:'理性成长风',explore:'旷野探索风',calm:'安静治愈风'},choices=palettes[mood];return{name:names[mood],mood,colors:choices[seed%choices.length],seed,variant:(seed>>>5)%6}}
function watercolorRand(seed){let value=seed>>>0;return()=>{value=(Math.imul(value,1664525)+1013904223)>>>0;return value/4294967296}}
