function crayonStroke(ctx,points,color,width,rand,closed=false){ctx.save();ctx.lineCap='round';ctx.lineJoin='round';for(let pass=0;pass<3;pass++){ctx.beginPath();points.forEach((p,i)=>{const x=p[0]+(rand()-.5)*4,y=p[1]+(rand()-.5)*4;i?ctx.lineTo(x,y):ctx.moveTo(x,y)});if(closed)ctx.closePath();ctx.strokeStyle=color;ctx.globalAlpha=.58+pass*.14;ctx.lineWidth=width*(.78+rand()*.34);ctx.stroke()}ctx.restore()}
