function quoteDoodleTypes(quote,theme){const semantic=/猫|宠物/.test(quote)?['cat','heart','cup']:/书|阅读|知识|学习|认知/.test(quote)?['book','lamp','sprout']:/家人|家庭|关系|陪伴|孩子|爱/.test(quote)?['people','house','heart']:/工作|行动|目标|成长|选择|改变/.test(quote)?['sprout','stairs','book']:/自由|远方|旅行|探索|世界/.test(quote)?['mountain','bird','sun']:/时间|习惯|每天|当下/.test(quote)?['sun','cloud','book']:[theme.mood==='connection'?'heart':'flower',theme.mood==='explore'?'bird':'sprout','cloud'];return[...semantic,'flower','house','bird','sun','cloud','book','sprout']}
