function drawCrayonBackground(ctx,theme,quote,format='portrait'){const w=ctx.canvas.width,h=ctx.canvas.height,sx=w/1080,sy=h/1440,elementScale=Math.sqrt(sx*sy),composition=crayonComposition(theme,quote,format),rand=watercolorRand((theme.seed^visualHash(format))>>>0),colors=['#41ad5d','#f28a28','#326fd1','#ef7487'],types=quoteDoodleTypes(quote,theme);ctx.clearRect(0,0,w,h);ctx.save();ctx.fillStyle=['#fff8ed','#fff5e9','#fff9f0'][composition.id%3];ctx.fillRect(0,0,w,h);ctx.globalAlpha=.12;for(let i=0;i<320;i++){ctx.fillStyle=i%4===0?colors[i%4]:'#80694f';ctx.fillRect(rand()*w,rand()*h,1+rand()*2.4,1+rand()*2.4)}ctx.globalAlpha=1;placeDoodleUnstretched(ctx,types[composition.id%3],composition.layout.hero,sx,sy,elementScale,colors,rand);for(let i=0;i<composition.layout.spots.length;i++){const original=composition.layout.spots[i],spot=[original[0]+(rand()-.5)*35,original[1]+(rand()-.5)*35,original[2]+rand()*18],type=types[(i+composition.id+1)%types.length];placeDoodleUnstretched(ctx,type,spot,sx,sy,elementScale,colors,rand)}for(let i=0;i<8+composition.id;i++){const x=(45+rand()*990)*sx,y=(50+rand()*1340)*sy,size=elementScale;crayonStroke(ctx,[[x,y],[x+(8+rand()*22)*size,y-(8+rand()*18)*size],[x+(18+rand()*24)*size,y]],colors[(i+composition.id)%colors.length],3*size,rand)}ctx.restore();return composition}
