function generateQuoteImage(index){currentShareIndex=index;const item=quoteSeeds[index],wechat=selectedPlatform()==='公众号';$('#standardSharePreview').classList.toggle('hidden',wechat);$('#wechatSharePreview').classList.toggle('hidden',!wechat);let theme;if(wechat){theme=drawCrayonQuoteArtwork($('#wechatCoverCanvas'),index,'cover');drawCrayonQuoteArtwork($('#wechatSquareCanvas'),index,'square');$('#shareStyleNote').textContent=`原文位置：${item.location} · 已生成手绘彩铅风公众号封面 2.35:1 与转发卡片 1:1`}else{theme=drawCrayonQuoteArtwork($('#quoteCanvas'),index,'portrait');$('#shareStyleNote').textContent=`原文位置：${item.location} · 已按书籍、原句和目标用户生成清新手绘彩铅风（构图 ${theme.variant+1}）`}$('#shareImageDialog').showModal()}
function drawWrappedText(ctx,text,x,y,maxWidth,lineHeight){const chars=[...text];let line='';let cursorY=y;for(const char of chars){const test=line+char;if(ctx.measureText(test).width>maxWidth&&line){ctx.fillText(line,x,cursorY);line=char;cursorY+=lineHeight}else line=test}if(line)ctx.fillText(line,x,cursorY)}
